styles:
.reader-quote {
  font-style: italic;
  color: #8b0000;
  text-shadow: 0 0 4px rgba(139, 0, 0, 0.6);
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 6px;
  color: #6b0000;
  opacity: 0.6;
}
.reader-dash {
  letter-spacing: 3px;
  color: #4a0040;
}
.reader-speak {
  color: #a03030;
  font-weight: 700;
  font-variant: small-caps;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.6em;
  line-height: 0.7;
  padding-right: 8px;
  padding-top: 4px;
  color: #8b0000;
  font-weight: 900;
  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.8);
  font-family: 'STKaiti', serif;
}
